entities = ["Falcon Cloud", "Acme Corp"]

RELATION_PATTERNS = [
    ("supplies", ["supplies", "provides service to"]),
    ("acquired", ["acquired", "purchased"]),
]

def extract_relation(sentence, entity_a, entity_b):
    # match the sentence against known relation phrases
    lowered = sentence.lower()
    for relation_name, phrases in RELATION_PATTERNS:
        for phrase in phrases:
            if phrase in lowered:
                # determine subject/object order from position in the sentence
                idx_a = lowered.find(entity_a.lower())
                idx_b = lowered.find(entity_b.lower())
                if idx_a == -1 or idx_b == -1:
                    return None
                if idx_a < idx_b:
                    return (entity_a, relation_name, entity_b)
                return (entity_b, relation_name, entity_a)
    return None

sentence = "Falcon Cloud supplies Acme Corp with hosting infrastructure."
triple = extract_relation(sentence, entities[0], entities[1])

print("Relation extraction result:")
print(triple if triple else "No relationship found.")
